const HTML = "<!DOCTYPE html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>チャット</title>\n<link rel=\"icon\" href=\"/manager/favicon.svg\" type=\"image/svg+xml\">\n<link rel=\"icon\" href=\"/manager/favicon-32.png\" sizes=\"32x32\" type=\"image/png\">\n<link rel=\"apple-touch-icon\" href=\"/manager/apple-touch-icon.png\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Geist:wght@400;600;800&family=Noto+Sans+JP:wght@400;600;800&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--bg:#f5f0eb;--panel:#fff;--soft:#f7f3ee;--line:#e6dfd6;--fg:#1a1a1a;--muted:#6b6259;--faint:#736a62;--field:#a39a90;--accent:#f59e0b;--accent-ink:#b45309;--accent-bg:#fef3c7;--brand:#ae5a5a;\n  --s-run:#1d6fb8;--s-wait:#b45309;--s-park:#6b6259;--s-done:#4d7c0f;color-scheme:light}\n@media (prefers-color-scheme:dark){:root:not([data-theme=light]){--bg:#1b1916;--panel:#24211d;--soft:#2b2823;--line:#38332c;--fg:#f1ece6;--muted:#b0a69b;--faint:#a0968b;--field:#6f665c;--accent:#fbbf24;--accent-ink:#fbbf24;--accent-bg:rgba(251,191,36,.14);--s-run:#7cb6ee;--s-wait:#fbbf24;--s-park:#b0a69b;--s-done:#a3c962;color-scheme:dark}}\n:root[data-theme=dark]{--bg:#1b1916;--panel:#24211d;--soft:#2b2823;--line:#38332c;--fg:#f1ece6;--muted:#b0a69b;--faint:#a0968b;--field:#6f665c;--accent:#fbbf24;--accent-ink:#fbbf24;--accent-bg:rgba(251,191,36,.14);--s-run:#7cb6ee;--s-wait:#fbbf24;--s-park:#b0a69b;--s-done:#a3c962;color-scheme:dark}\n*{box-sizing:border-box}\nhtml,body{margin:0;height:100%}\nbody{background:var(--bg);color:var(--fg);font:14px/1.6 \"Geist\",\"Noto Sans JP\",\"Hiragino Sans\",system-ui,sans-serif;-webkit-font-smoothing:antialiased}\nbutton,input,select,textarea{font:inherit;color:inherit}\nbutton{cursor:pointer}\na{color:var(--accent-ink)}\n.top{position:sticky;top:0;z-index:5;display:flex;align-items:center;gap:12px;height:56px;padding:0 16px;background:var(--panel);border-bottom:1px solid var(--line)}\n.top .logo{width:26px;height:26px;flex:none}\n.top h1{font-size:16px;font-weight:800;margin:0;white-space:nowrap}\n.grow{flex:1}\n#app{height:calc(100% - 56px)}\n.wrap{display:grid;grid-template-columns:196px minmax(300px,380px) 1fr;height:100%}\n.shelf{border-right:1px solid var(--line);background:var(--soft);overflow:auto;padding:12px 8px;display:flex;flex-direction:column;gap:2px}\n.shelf .h{font-size:11px;font-weight:700;color:var(--faint);padding:10px 8px 4px;letter-spacing:.04em}\n.shelf button{display:flex;align-items:center;gap:6px;width:100%;text-align:left;border:0;background:none;border-radius:8px;padding:7px 8px;font-size:13px}\n.shelf button:hover{background:var(--panel)}\n.shelf button[aria-pressed=true]{background:var(--panel);font-weight:700;box-shadow:inset 3px 0 0 var(--brand)}\n.shelf button .l{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.shelf button .n{font-size:12px;color:var(--faint)}\n.shelf button.un .l{color:var(--muted)}\n.shelf .ar{display:flex;align-items:center;gap:0}\n.shelf .ar .tg{width:22px;flex:none;padding:7px 0;justify-content:center;color:var(--faint);font-size:11px}\n.shelf .ar .tg[aria-expanded=true]{color:var(--fg)}\n.shelf .wk{padding-left:28px;font-size:12.5px}\n.shelf .wk .dot{width:7px;height:7px;border-radius:50%;flex:none;background:var(--s-run)}\n.shelf .wk .dot.w{background:var(--s-wait);border-radius:1px;transform:rotate(45deg)}\n.shelf .wk .dot.d{background:var(--s-done)}\n.wchip{font-size:11px;color:var(--brand);border:1px solid var(--line);border-radius:4px;padding:0 6px;max-width:160px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;background:none}\nbutton.wchip{cursor:pointer}\n.prs{list-style:none;margin:0;padding:0}\n.prs li{display:flex;gap:10px;align-items:baseline;padding:8px 4px;border-top:1px solid var(--line)}\n.prs li:first-child{border-top:0}\n.prs a{font-weight:600;word-break:break-all}\n.prs .d{font-size:12px;color:var(--faint);white-space:nowrap;margin-left:auto}\n.wchats .item{border:1px solid var(--line);border-radius:8px;margin-bottom:8px}\n.tl .cn{display:block;font-size:12px;color:var(--faint)}\n\n.area{font-size:11px;color:var(--muted);background:var(--soft);border-radius:4px;padding:0 6px;max-width:140px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.tl{list-style:none;margin:0;padding:0}\n.tl li{display:grid;grid-template-columns:96px 1fr;gap:10px;padding:8px 4px;border-top:1px solid var(--line)}\n.tl li:first-child{border-top:0}\n.tl .tm{font-size:12px;color:var(--faint);white-space:nowrap}\n.tl .tx{word-break:break-word}\n.tl .ask .tx{color:var(--muted)}\n.tl .ask .tx::before{content:\"最後の頼みごと：\";font-size:12px;color:var(--faint)}\n.act-day{font-size:13px;font-weight:800;margin:18px 0 6px}\n.act-day:first-child{margin-top:0}\n.act{display:grid;grid-template-columns:48px 1fr;gap:10px;width:100%;text-align:left;border:0;border-top:1px solid var(--line);background:none;padding:10px 4px}\n.act:hover{background:var(--soft)}\n.act .tm{font-size:12px;color:var(--faint);padding-top:2px}\n.act .tx{font-weight:600;word-break:break-word}\n.act.ask .tx{font-weight:400;color:var(--muted)}\n.act.ask .tx::before{content:\"最後の頼みごと：\";font-size:12px;color:var(--faint)}\n.act .who{display:flex;gap:6px;align-items:center;flex-wrap:wrap;font-size:12px;color:var(--faint);margin-top:2px}\n.side{border-right:1px solid var(--line);display:flex;flex-direction:column;min-height:0;background:var(--panel)}\n.tools{padding:12px;border-bottom:1px solid var(--line);display:flex;flex-direction:column;gap:10px}\n.search{position:relative}\n.search input{width:100%;height:38px;padding:0 34px 0 12px;border:1px solid var(--field);border-radius:8px;background:var(--panel)}\n.search input:focus{outline:2px solid var(--accent-ink);outline-offset:-1px}\n.search input::-webkit-search-cancel-button{display:none}\n.search .x{position:absolute;right:4px;top:4px;width:30px;height:30px;border:0;background:none;color:var(--muted);border-radius:6px}\n.tabs{display:flex;gap:4px;flex-wrap:wrap}\n.tab{height:30px;padding:0 10px;border:1px solid var(--line);border-radius:999px;background:var(--panel);font-size:13px;display:inline-flex;align-items:center;gap:6px}\n.tab[aria-pressed=true]{background:var(--fg);border-color:var(--fg);color:var(--panel)}\n.tab .n{font-size:12px;font-weight:600;opacity:.85}\n.tab.wait:not([aria-pressed=true]) .n{color:var(--s-wait)}\n.row2{display:flex;gap:8px;align-items:center;font-size:12px;color:var(--muted);flex-wrap:wrap}\n.row2 .tab{white-space:nowrap}\n.row2 select{height:30px;border:1px solid var(--field);border-radius:8px;background:var(--panel);padding:0 6px;font-size:13px}\n.list{overflow:auto;flex:1;min-height:0}\n.item{display:block;width:100%;text-align:left;border:0;border-bottom:1px solid var(--line);background:none;padding:10px 14px}\n.item:hover{background:var(--soft)}\n.item[aria-current=true]{background:var(--accent-bg)}\n.item .nm{font-weight:600;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}\n.item .dg{font-size:12px;color:var(--muted);margin-top:2px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}\n.item .mt{display:flex;gap:8px;align-items:center;font-size:12px;color:var(--faint);margin-top:4px;flex-wrap:wrap}\n.item .mt .cn{flex:1 1 0;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.st{display:inline-flex;align-items:center;gap:4px;font-size:12px;font-weight:600}\n.st::before{content:\"\";width:8px;height:8px;border-radius:50%;background:currentColor}\n.st.s-進行中{color:var(--s-run)}.st.s-判断待ち{color:var(--s-wait)}.st.s-寝かせ中{color:var(--s-park)}.st.s-閉じた{color:var(--s-done)}\n.st.s-判断待ち::before{border-radius:1px;transform:rotate(45deg);width:7px;height:7px}\n.st.s-閉じた::before{content:\"✓\";background:none;width:auto;height:auto}\n.ai{font-size:11px;font-weight:700;border:1px solid var(--line);border-radius:4px;padding:0 5px;color:var(--muted)}\n.hit .ref{font-weight:700;color:var(--brand);margin-right:6px}\n.hit mark{background:var(--accent-bg);color:inherit;padding:0 1px;border-radius:2px}\n.empty{padding:28px 16px;color:var(--muted);text-align:center;font-size:13px}\n.main{overflow:auto;min-height:0}\n.pane{max-width:860px;margin:0 auto;padding:24px 28px 80px}\n.back{display:none;margin-bottom:12px;height:32px;padding:0 10px;border:1px solid var(--line);border-radius:8px;background:var(--panel);font-size:13px}\n.card{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:18px 20px;margin-bottom:16px}\nh2.title{font-size:22px;font-weight:800;margin:0 0 6px;line-height:1.35;word-break:break-word}\n.meta{display:flex;gap:10px;flex-wrap:wrap;align-items:center;color:var(--muted);font-size:12px}\n.doing{margin-top:12px;padding:10px 12px;background:var(--soft);border-radius:8px}\n.doing .k{font-size:12px;color:var(--muted)}\n.acts{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}\n.btn{height:34px;padding:0 12px;border:1px solid var(--field);border-radius:8px;background:var(--panel);font-size:13px;display:inline-flex;align-items:center;gap:6px;text-decoration:none;color:var(--fg)}\n.btn.pri{background:#b45309;border-color:#b45309;color:#fff;font-weight:600}\n.btn:focus-visible,.item:focus-visible,.tab:focus-visible,.pin:focus-visible,.shelf button:focus-visible,.act:focus-visible{outline:2px solid var(--accent-ink);outline-offset:2px}\n.sec{font-size:13px;font-weight:700;color:var(--muted);margin:0 0 8px}\n.pins{list-style:none;margin:0;padding:0}\n.pin{display:flex;gap:10px;align-items:baseline;width:100%;text-align:left;border:0;border-top:1px solid var(--line);background:none;padding:10px 4px}\n.pin:first-child{border-top:0}\n.pin:hover{background:var(--soft)}\n.pin .no{font-weight:800;color:var(--brand);min-width:46px}\n.pin .t{flex:1;font-weight:600}\n.pin .d{font-size:12px;color:var(--faint);white-space:nowrap}\n.form{display:grid;gap:10px;margin-top:14px}\n.form label{display:grid;gap:4px;font-size:12px;color:var(--muted)}\n.form input,.form select,.form textarea{height:36px;border:1px solid var(--field);border-radius:8px;background:var(--panel);padding:0 10px;font-size:14px}\n.form textarea{height:64px;padding:8px 10px;resize:vertical}\n.hint{font-size:12px;color:var(--faint)}\n.body{word-break:break-word}\n.body>:first-child{margin-top:0}\n.body h1,.body h2,.body h3,.body h4{line-height:1.4;margin:1.2em 0 .5em}\n.body h1{font-size:20px}.body h2{font-size:18px}.body h3{font-size:16px}.body h4{font-size:14px}\n.body p{margin:.6em 0}\n.body ul,.body ol{padding-left:1.4em;margin:.5em 0}\n.body pre{background:var(--soft);border:1px solid var(--line);border-radius:8px;padding:10px 12px;overflow:auto;font-size:13px;line-height:1.5}\n.body code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.92em}\n.body :not(pre)>code{background:var(--soft);padding:1px 4px;border-radius:4px}\n.body table{border-collapse:collapse;margin:.8em 0;font-size:13px;display:block;overflow:auto}\n.body th,.body td{border:1px solid var(--line);padding:6px 8px;text-align:left;vertical-align:top}\n.body th{background:var(--soft)}\n.body blockquote{margin:.6em 0;padding:4px 12px;border-left:3px solid var(--line);color:var(--muted)}\n.body hr{border:0;border-top:1px solid var(--line);margin:1.2em 0}\n.ext{margin:0 12px 10px;padding:8px 10px;border:1px solid var(--line);border-radius:8px;background:var(--soft);font-size:12px;display:flex;gap:8px;align-items:center;flex-wrap:wrap}\n.ext .on{color:var(--s-done);font-weight:700}.ext .off{color:var(--s-wait);font-weight:700}\n.ext .grow{flex:1;min-width:0}\n.ext button{height:28px;padding:0 10px;border:1px solid var(--field);border-radius:8px;background:var(--panel);font-size:12px}\n.ext button.pri{background:#b45309;border-color:#b45309;color:#fff;font-weight:600}\nbody.panel .top{height:44px;padding:0 10px}body.panel .top h1{font-size:14px}body.panel .top .logo{width:20px;height:20px}\nbody.panel #app{height:calc(100% - 44px)}\n@media (pointer:fine){body.panel .tab,body.panel .btn,body.panel .back{min-height:0}body.panel .search input,body.panel .form input,body.panel .form select,body.panel .form textarea{font-size:13px}}\n.toast{position:fixed;left:50%;bottom:24px;transform:translateX(-50%);background:var(--fg);color:var(--panel);padding:8px 14px;border-radius:8px;font-size:13px;opacity:0;transition:opacity .15s;pointer-events:none;z-index:20}\n.toast.on{opacity:1}\n.login{max-width:420px;margin:12vh auto;text-align:center;padding:28px;background:var(--panel);border:1px solid var(--line);border-radius:14px}\n.login h2{margin:8px 0}\n.login p{color:var(--muted)}\n.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}\n@media (max-width:760px){\n  .wrap{grid-template-columns:1fr}\n  .wrap.detail .side{display:none}\n  .wrap:not(.detail) .main{display:none}\n  .back{display:inline-flex;align-items:center}\n  .pane{padding:16px 14px 60px}\n  .search input,.form input,.form select,.form textarea{font-size:16px}\n  .tab,.btn,.back{min-height:44px}\n  .top h1{font-size:15px}\n}\n.row2 .areasel{display:none;flex-wrap:wrap}\n.seg{display:none}\n.nbnarrow{display:none}\n@media (max-width:1100px){.nbnarrow{display:flex}}\n.filt>summary{list-style:none;cursor:pointer;font-size:12px;color:var(--muted);display:none;align-items:center;gap:6px;height:28px}\n.filt>summary::-webkit-details-marker{display:none}\n.filt>summary::before{content:\"▸\";font-size:10px}\n.filt[open]>summary::before{content:\"▾\"}\n.filt .in{display:flex;flex-direction:column;gap:8px}\n.shelf .foot{margin-top:auto;padding-top:12px}\n.wlist .ah{display:flex;align-items:center;gap:6px;padding:12px 14px 4px;font-size:11px;font-weight:700;color:var(--faint);letter-spacing:.04em}\n.wlist .wi{display:flex;align-items:center;gap:10px;width:100%;text-align:left;border:0;border-bottom:1px solid var(--line);background:none;padding:11px 14px}\n.wlist .wi:hover{background:var(--soft)}\n.wlist .wi .dot{width:8px;height:8px;border-radius:50%;flex:none;background:var(--s-run)}\n.wlist .wi .dot.w{background:var(--s-wait);border-radius:1px;transform:rotate(45deg)}\n.wlist .wi .l{flex:1;min-width:0;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.wlist .wi .n{font-size:12px;color:var(--faint);white-space:nowrap}\n.wlist .wi .wt{font-size:11px;font-weight:700;color:var(--s-wait);white-space:nowrap}\n@media (max-width:1100px){\n  .wrap{grid-template-columns:minmax(300px,400px) 1fr}.shelf{display:none}.row2 .areasel{display:inline-flex;gap:8px;align-items:center}\n  .seg{display:flex;gap:4px;padding:8px 10px;border-bottom:1px solid var(--line);background:var(--panel)}\n  .seg button{flex:1;height:32px;border:1px solid var(--line);border-radius:8px;background:var(--panel);font-size:13px;font-weight:600;color:var(--muted)}\n  .seg button[aria-selected=true]{background:var(--fg);border-color:var(--fg);color:var(--panel)}\n  .side.s-works .tools,.side.s-works .ext{display:none}\n  .tools{padding:10px;gap:8px}\n  .tabs{flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none;margin:0 -10px;padding:0 10px}\n  .tabs::-webkit-scrollbar{display:none}\n  .tab{flex:none}\n  .filt>summary{display:inline-flex}\n  .filt .row2 label{min-width:44px}\n  .ext{margin:0 10px 8px;padding:6px 8px;flex-wrap:nowrap}\n  .ext .grow{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n  .ext .grow br{display:none}\n}\n@media (max-width:760px){.wrap{grid-template-columns:minmax(0,1fr)}.side{min-width:0}.pane{padding:12px 10px 60px}.card{padding:14px;margin-bottom:12px}.acts{gap:6px}}\n</style>\n</head>\n<body>\n<header class=\"top\">\n  <img class=\"logo\" src=\"/manager/favicon.svg\" alt=\"\">\n  <h1>マネージャーくん</h1>\n  <span class=\"grow\"></span>\n  <div id=\"shell\"></div>\n</header>\n<div id=\"app\"></div>\n<div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n<script src=\"https://www.gstatic.com/firebasejs/10.12.5/firebase-app-compat.js\"></script>\n<script src=\"https://www.gstatic.com/firebasejs/10.12.5/firebase-auth-compat.js\"></script>\n<script type=\"module\">\nimport { mountAppShell, setTabTitle } from \"/manager/shell.js\";\n\nconst FB = __FIREBASE_WEB__;\nconst STATES = [\"進行中\", \"判断待ち\", \"寝かせ中\", \"閉じた\"];\nconst $ = (s, el = document) => el.querySelector(s);\nconst $$ = (s, el = document) => [...el.querySelectorAll(s)];\nconst esc = (s) => String(s ?? \"\").replace(/[&<>\"']/g, (c) => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\" }[c]));\nconst app = $(\"#app\");\nconst PANEL = new URLSearchParams(location.search).get(\"view\") === \"panel\" && window.parent !== window;\nif (PANEL) document.body.classList.add(\"panel\");\n\nfirebase.initializeApp(FB);\nconst auth = firebase.auth();\n\n/* ---- 外枠（右上の ？・アプリ一覧・アカウント） ---- */\nconst shell = mountAppShell({\n  appId: \"manager\", appName: \"マネージャーくん\",\n  source: {\n    user: () => auth.currentUser,\n    async profile() { return { role: \"admin\" }; },\n    async apps() { return []; },\n    async signOut() { await auth.signOut(); },\n    watch: (cb) => auth.onAuthStateChanged(cb),\n  },\n  portal: false,\n  manual: {\n    intro: \"Claude と GPT のチャットが、いま何をしていて、どこで止まっていて、前の回答がどこにあるかを 1 か所で開く台帳です。\",\n    sections: [\n      { title: \"見る\", items: [\n        { t: \"分野の棚\", d: \"左の棚は、Claude と ChatGPT のプロジェクト名でチャットを分けたものです（シアニンパネルが自動で入れます）。プロジェクトの外のチャットは「未分類」に入ります。違うときはチャットの「編集」で分野を直せます。\" },\n        { t: \"作業\", d: \"細い画面（シアニンパネル）では、上の「作業」で開いている作業が分野ごとに並び、1 回押せば作業が開きます。広い画面では、棚の分野の左の ▸ を押すと、その分野の作業（仕事のまとまり）が開きます。作業はチャットが自分で作り、同じ作業のチャットは同じ作業に入ります。作業を押すと、中のチャット・PR・やったこと・ピンが並びます。\" },\n        { t: \"今日・今週やったこと\", d: \"棚の上の「今日やったこと」「今週やったこと」で、分野をまたいで、チャットが残した「○○をした」が時刻順に並びます。道具を呼ばないチャットは、最後の頼みごとで代わりに出ます。\" },\n        { t: \"状態で絞る\", d: \"上の「進行中・判断待ち・寝かせ中・閉じた・すべて」を押すと、その状態のチャットだけが並びます。数は今の件数です。\" },\n        { t: \"探す\", d: \"検索窓に言葉を入れると、チャットの名前・何をしているか・ピンの題と全文から探します。空白で区切ると全部を含むものだけ。\", keys: [\"/\"] },\n        { t: \"やったこととピン\", d: \"チャットを押すと、右にやったことの時系列とピンの題が並びます。ピンの題を押すと全文が開きます。\" },\n      ] },\n      { title: \"使う\", items: [\n        { t: \"別のチャットへ持っていく\", d: \"別のチャットで「マネージャーくんの○○のピンを持ってきて」と題の言葉で頼むと、AI が全文を取ってきます。全文の上の「頼み方をコピー」でその文がコピーされます。\" },\n        { t: \"作業をタブで開く\", d: \"シアニンパネルの中で作業を開くと「タブで開く」が出ます。作業のチャットが作業の名前のタブのまとまりで開き、「たたむ」で折りたたみ、「閉じる」で消えます。作業が終わったら「済みにする」で棚から外れます。似た作業が分かれたときは「ほかの作業にまとめる」で 1 つにできます。\" },\n        { t: \"直す\", d: \"チャットの「編集」で、状態・何をしているか・分野・名前・住所を直せます。画面で決めた分野は自動で書き換わりません（空にすると自動に戻ります）。保存は ⌘／Ctrl＋Enter でも。\" },\n        { t: \"チャットで言うこと\", d: \"回答のあとに「これピン」と言うと、その回答が題つきで全文残ります。AI は区切りごとに「○○をした」を残し、判断を求めて止まるときは状態を「判断待ち」にします。\" },\n      ] },\n    ],\n  },\n});\nshell.attach($(\"#shell\"));\n\n/* ---- 読み口（/manager/api） ---- */\nasync function api(path, opts = {}) {\n  const u = auth.currentUser;\n  if (!u) throw new Error(\"ログインしていません\");\n  const token = await u.getIdToken();\n  const r = await fetch(\"/manager/api/\" + path, { ...opts, headers: { Authorization: \"Bearer \" + token, \"Content-Type\": \"application/json\", ...(opts.headers || {}) } });\n  const b = await r.json().catch(() => null);\n  if (!r.ok || !b || b.ok === false) throw new Error((b && b.message) || (\"読み込めませんでした（\" + r.status + \"）\"));\n  return b;\n}\n\nlet toastT = null;\nfunction toast(msg) { const t = $(\"#toast\"); t.textContent = msg; t.classList.add(\"on\"); clearTimeout(toastT); toastT = setTimeout(() => t.classList.remove(\"on\"), 1800); }\nasync function copy(text, msg) { try { await navigator.clipboard.writeText(text); toast(msg); } catch { toast(\"コピーできませんでした\"); } }\n\n/* ---- 状態 ---- */\nconst S = {\n  filter: (() => { try { return localStorage.getItem(\"mk:filter\") || \"open\"; } catch { return \"open\"; } })(),\n  ai: \"\", q: \"\", chats: [], counts: {}, hits: null, sel: null, chat: null, pins: [], pin: null, editing: false, loading: false, err: \"\",\n  full: null, ext: null, ini: \"\", inis: [], ses: null, nb: null, view: null,\n  area: (() => { try { return localStorage.getItem(\"mk:area\") || \"\"; } catch { return \"\"; } })(), areas: [], done: [], ask: null, act: null,\n  works: [], work: null, wedit: false,\n  seg: (() => { try { return localStorage.getItem(\"mk:seg\") || \"works\"; } catch { return \"works\"; } })(),\n  open: (() => { try { return new Set(JSON.parse(localStorage.getItem(\"mk:open\") || \"[]\")); } catch { return new Set(); } })(),\n};\nconst rel = (s) => {\n  const t = Date.parse(String(s).replace(\" \", \"T\") + \":00+09:00\"); if (isNaN(t)) return s || \"\";\n  const m = Math.round((Date.now() - t) / 60000);\n  if (m < 1) return \"たった今\"; if (m < 60) return m + \"分前\"; const h = Math.round(m / 60); if (h < 24) return h + \"時間前\";\n  const d = Math.round(h / 24); return d < 30 ? d + \"日前\" : String(s).slice(0, 10);\n};\nconst stBadge = (s) => `<span class=\"st s-${esc(s)}\">${esc(s)}</span>`;\nconst aiBadge = (a) => `<span class=\"ai\">${a === \"gpt\" ? \"GPT\" : \"Claude\"}</span>`;\n\n/* ---- 簡単なマークダウン（見出し・箇条書き・番号・表・コード・引用・太字・リンク）。字は全部エスケープしてから組む ---- */\nfunction inline(s) {\n  return esc(s)\n    .replace(/`([^`]+)`/g, \"<code>$1</code>\")\n    .replace(/\\*\\*([^*]+)\\*\\*/g, \"<strong>$1</strong>\")\n    .replace(/\\[([^\\]]+)\\]\\((https?:\\/\\/[^\\s)]+)\\)/g, '<a href=\"$2\" target=\"_blank\" rel=\"noopener\">$1</a>')\n    .replace(/(^|[\\s（(])(https?:\\/\\/[^\\s<）)]+)/g, '$1<a href=\"$2\" target=\"_blank\" rel=\"noopener\">$2</a>');\n}\nfunction md(src) {\n  const lines = String(src ?? \"\").replace(/\\r\\n?/g, \"\\n\").split(\"\\n\");\n  const out = []; let i = 0;\n  const isTable = (a, b) => /^\\s*\\|.*\\|\\s*$/.test(a || \"\") && /^\\s*\\|?\\s*:?-{2,}/.test(b || \"\");\n  const cells = (l) => l.trim().replace(/^\\|/, \"\").replace(/\\|$/, \"\").split(\"|\").map((c) => c.trim());\n  while (i < lines.length) {\n    const l = lines[i];\n    if (/^```/.test(l)) { const buf = []; i++; while (i < lines.length && !/^```/.test(lines[i])) buf.push(lines[i++]); i++; out.push(\"<pre><code>\" + esc(buf.join(\"\\n\")) + \"</code></pre>\"); continue; }\n    if (isTable(l, lines[i + 1])) {\n      const head = cells(l); i += 2; const rows = [];\n      while (i < lines.length && /^\\s*\\|/.test(lines[i])) rows.push(cells(lines[i++]));\n      out.push(\"<table><thead><tr>\" + head.map((c) => \"<th>\" + inline(c) + \"</th>\").join(\"\") + \"</tr></thead><tbody>\" + rows.map((r) => \"<tr>\" + r.map((c) => \"<td>\" + inline(c) + \"</td>\").join(\"\") + \"</tr>\").join(\"\") + \"</tbody></table>\");\n      continue;\n    }\n    let m;\n    if ((m = l.match(/^(#{1,4})\\s+(.*)$/))) { out.push(`<h${m[1].length}>` + inline(m[2]) + `</h${m[1].length}>`); i++; continue; }\n    if (/^\\s*([-*_])\\s*\\1\\s*\\1[\\s\\1]*$/.test(l)) { out.push(\"<hr>\"); i++; continue; }\n    if (/^\\s*>/.test(l)) { const buf = []; while (i < lines.length && /^\\s*>/.test(lines[i])) buf.push(lines[i++].replace(/^\\s*>\\s?/, \"\")); out.push(\"<blockquote>\" + md(buf.join(\"\\n\")) + \"</blockquote>\"); continue; }\n    if (/^\\s*([-*+・]|\\d+[.)])\\s+/.test(l)) {\n      const buf = [];\n      while (i < lines.length && (/^\\s*([-*+・]|\\d+[.)])\\s+/.test(lines[i]) || (/^\\s{2,}\\S/.test(lines[i]) && buf.length))) buf.push(lines[i++]);\n      out.push(list(buf)); continue;\n    }\n    if (!l.trim()) { i++; continue; }\n    const buf = [];\n    while (i < lines.length && lines[i].trim() && !/^(```|#{1,4}\\s|\\s*>|\\s*([-*+・]|\\d+[.)])\\s+)/.test(lines[i]) && !isTable(lines[i], lines[i + 1])) buf.push(inline(lines[i++]));\n    out.push(\"<p>\" + buf.join(\"<br>\") + \"</p>\");\n  }\n  return out.join(\"\");\n}\nfunction list(buf) {\n  const ind = (l) => l.match(/^\\s*/)[0].replace(/\\t/g, \"  \").length;\n  const base = ind(buf[0]);\n  const ordered = /^\\s*\\d+[.)]/.test(buf[0]);\n  let html = ordered ? \"<ol>\" : \"<ul>\"; let k = 0;\n  while (k < buf.length) {\n    const text = buf[k].replace(/^\\s*([-*+・]|\\d+[.)])\\s+/, \"\"); k++;\n    const sub = [];\n    while (k < buf.length && ind(buf[k]) > base) sub.push(buf[k++]);\n    html += \"<li>\" + inline(text) + (sub.length && /^\\s*([-*+・]|\\d+[.)])\\s+/.test(sub[0]) ? list(sub) : sub.map((x) => \"<br>\" + inline(x.trim())).join(\"\")) + \"</li>\";\n  }\n  return html + (ordered ? \"</ol>\" : \"</ul>\");\n}\n\n/* ---- 住所（#c12・#p12-3）で開いているものを覚える。押して戻れる ---- */\nfunction setHash(h) { if (location.hash !== h) history.pushState(null, \"\", h || location.pathname); }\nfunction readHash() {\n  const h = location.hash; let m;\n  if ((m = h.match(/^#p(\\d+)-(\\d+)$/))) return { chat: +m[1], pin: +m[2] };\n  if ((m = h.match(/^#c(\\d+)$/))) return { chat: +m[1], pin: null };\n  if ((m = h.match(/^#w(\\d+)$/))) return { chat: null, pin: null, work: +m[1] };\n  return { chat: null, pin: null };\n}\n\n/* ---- 読み込み ---- */\nasync function loadList() {\n  S.loading = true; S.err = \"\"; render();\n  try {\n    const st = S.filter === \"open\" ? \"\" : S.filter;\n    const b = await api(\"chats?state=\" + encodeURIComponent(st) + \"&ai=\" + encodeURIComponent(S.ai) + \"&initiative=\" + encodeURIComponent(S.ini) + \"&area=\" + encodeURIComponent(S.area));\n    S.chats = b.chats; S.counts = b.counts; S.areas = b.areas || [];\n    try { S.works = (await api(\"works\")).works || []; } catch { S.works = []; }\n  } catch (e) { S.err = e.message; }\n  S.loading = false; render();\n}\nlet qT = null;\nfunction onSearch(v) {\n  S.q = v; clearTimeout(qT);\n  if (!v.trim()) { S.hits = null; render(); return; }\n  qT = setTimeout(async () => {\n    const q = S.q;\n    try { const b = await api(\"search?q=\" + encodeURIComponent(q)); if (q === S.q) { S.hits = b.hits; render(); } }\n    catch (e) { S.err = e.message; render(); }\n  }, 180);\n}\nasync function openChat(no, pin = null, push = true) {\n  S.sel = no; S.editing = false; S.pin = null; S.full = null;\n  if (push) setHash(pin ? `#p${no}-${pin}` : `#c${no}`);\n  render();\n  try {\n    const b = await api(\"chat?no=\" + no);\n    S.chat = b.chat; S.pins = b.pins; S.done = b.done || []; S.ask = b.最後の頼みごと || null; S.ses = null; S.view = null;\n    setTabTitle(S.chat.名前, \"チャット\");\n    api(\"sessions?no=\" + no).then((x) => { if (S.chat && S.chat.番号 === no) { S.ses = x.sessions; if (!S.pin && !S.full && !S.editing) render(); } }).catch(() => {});\n    if (pin) await openPin(no, pin, false); else render();\n  } catch (e) { S.chat = null; S.err = e.message; render(); }\n}\nasync function openPin(no, n, push = true) {\n  if (push) setHash(`#p${no}-${n}`);\n  try {\n    const b = await api(`pin?chat=${no}&n=${n}`);\n    S.pin = b.pin; render();\n    $(\".main\").scrollTop = 0;\n    setTabTitle(S.pin.題, \"チャット\");\n  } catch (e) { toast(e.message); }\n}\nasync function openFull() {\n  try { const b = await api(\"transcript?no=\" + S.sel); S.full = b; render(); $(\".main\").scrollTop = 0; }\n  catch (e) { toast(e.message); }\n}\n\n/* ---- シアニンパネルの中だけ：自動で残す拡張をつなぐ（鍵は書くだけ。パネルの部品 bridge-manager.js が受け取って持つ） ---- */\nfunction toPanel(msg) { try { window.parent.postMessage({ src: \"manager\", ...msg }, \"*\"); } catch {} }\naddEventListener(\"message\", (e) => {\n  const m = e.data || {};\n  if (!PANEL || e.source !== window.parent || m.src !== \"manager-ext\") return;\n  if (m.type === \"ext-state\") { S.ext = m; renderExt(); }\n  if (m.type === \"tabs-done\") toast(m.message || (m.ok ? \"タブを動かしました\" : \"タブを動かせませんでした\"));\n});\nasync function extConnect() {\n  try { const b = await api(\"ext-key\", { method: \"POST\", body: \"{}\" }); toPanel({ type: \"ext-key\", key: b.key, base: location.origin }); toast(\"つなぎました。開いたチャットを自動で残します\"); }\n  catch (e) { toast(e.message); }\n}\nasync function extRevoke() {\n  try { await api(\"ext-revoke\", { method: \"POST\", body: \"{}\" }); toPanel({ type: \"ext-forget\" }); toast(\"自動で残すのを止めました\"); }\n  catch (e) { toast(e.message); }\n}\nfunction renderExt() {\n  const el = $(\".ext\"); if (!el) return;\n  const x = S.ext;\n  if (!x) { el.innerHTML = `<span class=\"grow\">シアニンパネルを確かめています…</span>`; return; }\n  if (!x.has_key) { el.innerHTML = `<span class=\"grow\"><span class=\"off\">自動で残す：まだ</span><br>開いた Claude と ChatGPT のチャットを全文で台帳へ</span><button class=\"pri\" data-act=\"extconnect\">この拡張をつなぐ</button>`; return; }\n  const l = x.last;\n  const last = !l ? \"まだ残していません\" : l.error ? \"最後：\" + esc(l.error) : \"最後に残した：#\" + l.no + \" \" + esc(l.name || \"\") + \"（\" + esc(l.at || \"\") + \"）\";\n  el.innerHTML = `<span class=\"grow\"><span class=\"on\">自動で残す：オン</span><br>${last}</span><button data-act=\"extrevoke\">止める</button>`;\n}\n\nasync function save(form) {\n  const fd = new FormData(form);\n  const body = { no: S.chat.番号, state: fd.get(\"state\"), doing: fd.get(\"doing\"), name: fd.get(\"name\"), url: fd.get(\"url\"), initiative: fd.get(\"initiative\") || \"\", area: fd.get(\"area\") || \"\" };\n  const wk = String(fd.get(\"work\") || \"\").trim();\n  if (wk !== (S.chat.作業 ? S.chat.作業.名前 : \"\")) body.work = wk; // 変えたときだけ送る（済みの作業に同じ名前の新しい作業ができないように）\n  try {\n    const b = await api(\"update\", { method: \"POST\", body: JSON.stringify(body) });\n    S.chat = b.chat; S.editing = false; toast(\"「\" + S.chat.名前 + \"」を保存しました\" + (b.warning ? \"（\" + b.warning + \"）\" : \"\"));\n    await loadList();\n  } catch (e) { toast(e.message); }\n}\n\n/* ---- 描く ---- */\nfunction worksListHtml() {\n  if (!S.works.length) return `<div class=\"empty\">開いている作業はまだありません。<br>チャットが台帳を立てると、作業がここに並びます。</div>`;\n  const groups = new Map();\n  for (const w of S.works) { const k = w.分野 || \"未分類\"; if (!groups.has(k)) groups.set(k, []); groups.get(k).push(w); }\n  return `<div class=\"wlist\">` + [...groups].map(([k, ws]) => `<div class=\"ah\">${esc(k)}</div>` + ws.map((w) => `<button class=\"wi\" data-work=\"${w.番号}\"><span class=\"dot${w.状態 === \"判断待ち\" ? \" w\" : \"\"}\"></span><span class=\"l\">${esc(w.名前)}</span>${w.判断待ち ? `<span class=\"wt\">判断待ち ${w.判断待ち}</span>` : \"\"}<span class=\"n\">チャット ${w.チャットの数}</span></button>`).join(\"\")).join(\"\") + `</div>`;\n}\nfunction listHtml() {\n  if (matchMedia(\"(max-width:1100px)\").matches && S.seg === \"works\" && !S.hits) return worksListHtml();\n  if (S.hits) {\n    if (!S.hits.length) return `<div class=\"empty\">「${esc(S.q)}」に当たるものはありません</div>`;\n    const words = S.q.trim().split(/[\\s　]+/).filter(Boolean);\n    const hl = (s) => { let h = esc(s); words.forEach((w) => { const re = new RegExp(w.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\"), \"gi\"); h = h.replace(re, (x) => \"<mark>\" + x + \"</mark>\"); }); return h; };\n    return S.hits.map((h) => h.種類 === \"ピン\"\n      ? `<button class=\"item hit\" data-pin=\"${h.チャット番号}-${h.番号}\"><div class=\"nm\"><span class=\"ref\">ピン</span>${hl(h.題)}</div><div class=\"dg\">${hl(h.抜き出し)}</div><div class=\"mt\">${stBadge(h.状態)}<span class=\"cn\">${esc(h.チャットの名前)}</span><span>${esc(rel(h.日時))}</span></div></button>`\n      : `<button class=\"item hit\" data-chat=\"${h.チャット番号}\"><div class=\"nm\">${hl(h.題)}</div><div class=\"dg\">${hl(h.抜き出し)}</div><div class=\"mt\">${stBadge(h.状態)}<span>チャット</span><span>${esc(rel(h.日時))}</span></div></button>`).join(\"\");\n  }\n  if (S.loading && !S.chats.length) return `<div class=\"empty\">読み込んでいます…</div>`;\n  if (S.err && !S.chats.length) return `<div class=\"empty\">${esc(S.err)}</div>`;\n  if (!S.chats.length) return `<div class=\"empty\">${S.filter === \"判断待ち\" ? \"判断待ちのチャットはありません\" : \"この状態のチャットはありません\"}${S.area ? `（分野「${esc(S.area)}」）` : \"\"}</div>`;\n  return S.chats.map((c) => `<button class=\"item\" data-chat=\"${c.番号}\" aria-current=\"${S.sel === c.番号}\">\n    <div class=\"nm\">${esc(c.名前)}</div>${c.何をしているか ? `<div class=\"dg\">${esc(c.何をしているか)}</div>` : \"\"}\n    <div class=\"mt\">${stBadge(c.状態)}${aiBadge(c.AI)}${!S.area && c.分野 ? `<span class=\"area\">${esc(c.分野)}</span>` : \"\"}${c.作業 ? `<span class=\"wchip\">${esc(c.作業.名前)}</span>` : \"\"}<span>ピン ${c.ピンの数}</span><span>${esc(rel(c.最後に触った))}</span></div></button>`).join(\"\");\n}\nfunction tabsHtml() {\n  const c = S.counts || {};\n  const open = (c.進行中 || 0) + (c.判断待ち || 0) + (c.寝かせ中 || 0);\n  const t = (k, label, n, cls = \"\") => `<button class=\"tab ${cls}\" data-filter=\"${k}\" aria-pressed=\"${S.filter === k}\">${label}${n === null ? \"\" : ` <span class=\"n\">${n}</span>`}</button>`;\n  return t(\"open\", \"閉じた以外\", open) + t(\"判断待ち\", \"判断待ち\", c.判断待ち || 0, \"wait\") + t(\"進行中\", \"進行中\", c.進行中 || 0) + t(\"寝かせ中\", \"寝かせ中\", c.寝かせ中 || 0) + t(\"閉じた\", \"閉じた\", c.閉じた || 0) + t(\"すべて\", \"すべて\", null);\n}\nfunction shelfHtml() {\n  const b = (attrs, label, n, cls = \"\", on = false) => `<button type=\"button\" ${attrs} class=\"${cls}\" aria-pressed=\"${on}\"><span class=\"l\">${esc(label)}</span>${n === null ? \"\" : `<span class=\"n\">${n}</span>`}</button>`;\n  const total = S.areas.reduce((a, x) => a + x.閉じた以外, 0);\n  return `<div class=\"h\">やったこと</div>`\n    + b('data-act=\"act-today\"', \"今日やったこと\", null, \"\", S.view === \"activity\" && S.act && S.act.range === \"today\")\n    + b('data-act=\"act-week\"', \"今週やったこと\", null, \"\", S.view === \"activity\" && S.act && S.act.range === \"week\")\n    + `<div class=\"h\">分野（閉じた以外の数）</div>`\n    + b('data-area=\"\"', \"すべての分野\", total, \"\", !S.area)\n    + S.areas.map((a) => {\n      const ws = worksIn(a.分野);\n      const open = S.open.has(a.分野);\n      const tg = ws.length ? `<button type=\"button\" class=\"tg\" data-toggle=\"${esc(a.分野)}\" aria-expanded=\"${open}\" aria-label=\"${esc(a.分野)}の作業を${open ? \"たたむ\" : \"開く\"}\">${open ? \"▾\" : \"▸\"}</button>` : `<span class=\"tg\" style=\"display:inline-block;width:22px\"></span>`;\n      const row = `<div class=\"ar\">${tg}${b(`data-area=\"${esc(a.分野)}\"`, a.分野, a.閉じた以外, a.分野 === \"未分類\" ? \"un\" : \"\", S.area === a.分野 && S.view !== \"work\")}</div>`;\n      return row + (open ? ws.map((w) => `<button type=\"button\" class=\"wk\" data-work=\"${w.番号}\" aria-pressed=\"${S.view === \"work\" && S.work && S.work.work.番号 === w.番号}\"><span class=\"dot${w.状態 === \"判断待ち\" ? \" w\" : w.状態 === \"済み\" ? \" d\" : \"\"}\"></span><span class=\"l\">${esc(w.名前)}</span><span class=\"n\">${w.チャットの数}</span></button>`).join(\"\") : \"\");\n    }).join(\"\")\n    + `<div class=\"foot\"><button type=\"button\" data-act=\"notebook\" aria-pressed=\"${S.view === \"notebook\"}\"><span class=\"l\">NotebookLM へ書き出す</span></button></div>`;\n}\nfunction worksIn(area) { return S.works.filter((w) => (w.分野 || \"未分類\") === area); }\nfunction workSelHtml() {\n  const groups = new Map();\n  for (const w of S.works) { const k = w.分野 || \"未分類\"; if (!groups.has(k)) groups.set(k, []); groups.get(k).push(w); }\n  return `<option value=\"\">作業を開く</option>` + [...groups].map(([k, ws]) => `<optgroup label=\"${esc(k)}\">${ws.map((w) => `<option value=\"${w.番号}\">${esc(w.名前)}${w.状態 === \"判断待ち\" ? \"（判断待ち）\" : \"\"}</option>`).join(\"\")}</optgroup>`).join(\"\");\n}\nfunction toggleArea(a) { if (S.open.has(a)) S.open.delete(a); else S.open.add(a); try { localStorage.setItem(\"mk:open\", JSON.stringify([...S.open])); } catch {} render(); }\nasync function openWork(id, push = true) {\n  S.view = \"work\"; S.sel = null; S.pin = null; S.full = null; S.wedit = false;\n  if (push) setHash(`#w${id}`);\n  if (!S.work || S.work.work.番号 !== id) S.work = null;\n  render();\n  try { const b = await api(\"work?id=\" + id); S.work = b; setTabTitle(b.work.名前, \"チャット\"); const a = b.work.分野 || \"未分類\"; if (!S.open.has(a)) { S.open.add(a); try { localStorage.setItem(\"mk:open\", JSON.stringify([...S.open])); } catch {} } render(); }\n  catch (e) { toast(e.message); }\n}\nasync function workUpdate(patch, msg) {\n  try { await api(\"work-update\", { method: \"POST\", body: JSON.stringify({ id: S.work.work.番号, ...patch }) }); toast(msg); await loadList(); await openWork(S.work.work.番号, false); }\n  catch (e) { toast(e.message); }\n}\nasync function workMerge(to) {\n  const from = S.work.work.番号;\n  try { await api(\"work-merge\", { method: \"POST\", body: JSON.stringify({ from, to }) }); toast(\"1 つにまとめました\"); await loadList(); setHash(`#w${to}`); await openWork(to, false); }\n  catch (e) { toast(e.message); }\n}\nfunction workTabs(type) {\n  const W = S.work; if (!W) return;\n  const urls = W.chats.map((c) => c.住所).filter((u) => /^https:\\/\\/(claude\\.ai\\/chat\\/|chatgpt\\.com\\/)/.test(u || \"\"));\n  if (type === \"tabs-open\" && !urls.length) { toast(\"開ける住所のあるチャットがありません\"); return; }\n  toPanel({ type, name: W.work.名前, urls });\n}\nfunction workHtml() {\n  const back = `<button class=\"back\" data-act=\"back\">← 一覧へ</button>`;\n  const W = S.work;\n  if (!W) return back + `<div class=\"empty\">読み込んでいます…</div>`;\n  const w = W.work;\n  const others = S.works.filter((x) => x.番号 !== w.番号 && (x.分野 || \"未分類\") === (w.分野 || \"未分類\"));\n  const tabs = PANEL ? `<button class=\"btn pri\" data-act=\"wopen\">タブで開く</button><button class=\"btn\" data-act=\"wfold\">たたむ</button><button class=\"btn\" data-act=\"wclose\">閉じる</button>` : \"\";\n  const edit = S.wedit ? `<form class=\"form\" id=\"wedit\"><label>作業の名前<input name=\"name\" maxlength=\"80\" value=\"${esc(w.名前)}\" required></label>\n      ${others.length ? `<label>ほかの作業にまとめる（この作業のチャットを移して、この作業を消す）<select name=\"to\"><option value=\"\">まとめない</option>${others.map((x) => `<option value=\"${x.番号}\">${esc(x.名前)}</option>`).join(\"\")}</select></label>` : \"\"}\n      <div class=\"acts\" style=\"margin-top:0\"><button class=\"btn pri\" type=\"submit\">保存</button><button class=\"btn\" type=\"button\" data-act=\"wcancel\">キャンセル</button></div></form>` : \"\";\n  return back + `<div class=\"card\">\n    <div class=\"meta\"><span class=\"ref\" style=\"font-weight:800;color:var(--brand)\">作業</span><span class=\"area\">${esc(w.分野 || \"未分類\")}</span>${stBadge(w.状態 === \"済み\" ? \"閉じた\" : w.状態).replace(\">閉じた<\", \">済み<\")}<span>チャット ${w.チャットの数}</span><span>最後に触った ${esc(w.最後に触った)}</span></div>\n    <h2 class=\"title\" style=\"margin-top:6px\">${esc(w.名前)}</h2>\n    ${S.wedit ? edit : `<div class=\"acts\">${tabs}${w.状態 === \"済み\" ? `<button class=\"btn\" data-act=\"wreopen\">進行中に戻す</button>` : `<button class=\"btn\" data-act=\"wdone\">済みにする</button>`}<button class=\"btn\" data-act=\"wedit\">名前を直す・まとめる</button></div>`}\n  </div>\n  <div class=\"card\"><h3 class=\"sec\">チャット（${W.chats.length}）</h3><div class=\"wchats\">${W.chats.length ? W.chats.map((c) => `<button class=\"item\" data-chat=\"${c.番号}\"><div class=\"nm\">${esc(c.名前)}</div>${c.何をしているか ? `<div class=\"dg\">${esc(c.何をしているか)}</div>` : \"\"}<div class=\"mt\">${stBadge(c.状態)}${aiBadge(c.AI)}<span>ピン ${c.ピンの数}</span><span>${esc(rel(c.最後に触った))}</span></div></button>`).join(\"\") : `<div class=\"hint\">この作業のチャットはまだありません。</div>`}</div></div>\n  ${W.prs.length ? `<div class=\"card\"><h3 class=\"sec\">PR（${W.prs.length}）</h3><ul class=\"prs\">${W.prs.map((p) => `<li><a href=\"${esc(p.住所)}\" target=\"_blank\" rel=\"noopener\">${esc(p.住所.replace(/^https:\\/\\/github\\.com\\//, \"\"))} ↗</a><span class=\"d\">${esc(p.時刻.slice(5).replace(\"-\", \"/\"))}</span></li>`).join(\"\")}</ul></div>` : \"\"}\n  <div class=\"card\"><h3 class=\"sec\">やったこと（${W.done.length}）</h3>${W.done.length ? `<ul class=\"tl\">${W.done.map((d) => `<li><span class=\"tm\">${esc(String(d.時刻).slice(5).replace(\"-\", \"/\"))}</span><span class=\"tx\">${esc(d.やったこと)}${d.住所 ? ` <a href=\"${esc(d.住所)}\" target=\"_blank\" rel=\"noopener\">↗</a>` : \"\"}<span class=\"cn\">${esc(d.チャットの名前)}</span></span></li>`).join(\"\")}</ul>` : `<div class=\"hint\">まだありません。チャットが区切りごとに「○○をした」を残すと、ここに並びます。</div>`}</div>\n  <div class=\"card\"><h3 class=\"sec\">ピン（${W.pins.length}）</h3>${W.pins.length ? `<div class=\"pins\">${W.pins.map((p) => `<button class=\"pin\" data-pin=\"${p.チャット番号}-${p.番号}\"><span class=\"t\">${esc(p.題)}</span><span class=\"d\">${esc(p.作った)}</span></button>`).join(\"\")}</div>` : `<div class=\"hint\">まだありません。</div>`}</div>`;\n}\nfunction areaSelHtml() {\n  return `<option value=\"\">すべての分野</option>` + S.areas.map((a) => `<option value=\"${esc(a.分野)}\"${S.area === a.分野 ? \" selected\" : \"\"}>${esc(a.分野)}（${a.閉じた以外}）</option>`).join(\"\");\n}\nfunction setArea(v) { S.area = v; try { localStorage.setItem(\"mk:area\", v); } catch {} loadList(); }\nasync function openActivity(range) {\n  S.view = \"activity\"; S.sel = null; S.pin = null; S.full = null; S.act = { range, items: null }; setHash(\"\"); setTabTitle(range === \"week\" ? \"今週やったこと\" : \"今日やったこと\", \"チャット\"); render();\n  try { const b = await api(\"activity?range=\" + range); if (S.act && S.act.range === range) { S.act.items = b.items; render(); } } catch (e) { toast(e.message); }\n}\nfunction activityHtml() {\n  const a = S.act; const back = `<button class=\"back\" data-act=\"back\">← 一覧へ</button>`;\n  const head = `<div class=\"card\"><h2 class=\"title\">${a.range === \"week\" ? \"今週やったこと\" : \"今日やったこと\"}</h2><div class=\"meta\"><span>${a.range === \"week\" ? \"月曜から\" : \"今日 0 時から\"}・新しい順</span>${a.items ? `<span>${a.items.length} 件</span>` : \"\"}<span class=\"grow\"></span><button class=\"btn\" data-act=\"${a.range === \"week\" ? \"act-today\" : \"act-week\"}\">${a.range === \"week\" ? \"今日だけにする\" : \"今週にひろげる\"}</button></div></div>`;\n  if (!a.items) return back + head + `<div class=\"empty\">読み込んでいます…</div>`;\n  if (!a.items.length) return back + head + `<div class=\"card\"><div class=\"hint\">まだ何も残っていません。チャットが区切りごとに「○○をした」を残すと、ここに並びます。</div></div>`;\n  const days = new Map();\n  for (const it of a.items) { const d = String(it.時刻).slice(0, 10); if (!days.has(d)) days.set(d, []); days.get(d).push(it); }\n  const wd = (d) => \"日月火水木金土\"[new Date(d + \"T00:00:00+09:00\").getDay()];\n  return back + head + `<div class=\"card\">` + [...days].map(([d, xs]) => `<div class=\"act-day\">${esc(d.slice(5).replace(\"-\", \"/\"))}（${wd(d)}）</div>` + xs.map((it) => `<button class=\"act${it.種類 === \"最後の頼みごと\" ? \" ask\" : \"\"}\" data-chat=\"${it.チャット番号}\"><span class=\"tm\">${esc(String(it.時刻).slice(11))}</span><span><div class=\"tx\">${esc(it.中身)}</div><div class=\"who\">${it.分野 ? `<span class=\"area\">${esc(it.分野)}</span>` : \"\"}${aiBadge(it.AI)}<span>${esc(it.チャットの名前)}</span>${stBadge(it.状態)}</div></span></button>`).join(\"\")).join(\"\") + `</div>`;\n}\nfunction notebookHtml() {\n  const n = S.nb;\n  if (!n) return `<div class=\"empty\">読み込んでいます…</div>`;\n  return `<div class=\"card\"><h2 class=\"title\">NotebookLM へ書き出す</h2>\n    <div class=\"hint\" style=\"margin-bottom:12px\">ピンの全文と、チャットごとの状態の1行を、Google ドキュメント1枚へ30分ごとに書き直します（中身が変わったときだけ）。NotebookLM にそのドキュメントを1回入れれば、あとは自動で追いかけます。</div>\n    <div class=\"form\" style=\"margin-top:0\">\n      <div><div class=\"hint\">1. ドライブで空のドキュメントを作り、次のメールアドレスへ「編集者」で共有する</div>\n        ${n.share_to ? `<div class=\"acts\" style=\"margin-top:6px\"><code style=\"padding:4px 8px;background:var(--soft);border-radius:6px\">${esc(n.share_to)}</code><button class=\"btn\" type=\"button\" data-act=\"copysa\">コピー</button></div>` : `<div class=\"hint\">（メールアドレスを読めませんでした）</div>`}</div>\n      <label>2. そのドキュメントの住所を貼る<input id=\"nbdoc\" placeholder=\"https://docs.google.com/document/d/…\" value=\"${esc(n.doc_url || \"\")}\"></label>\n      <div class=\"acts\" style=\"margin-top:0\"><button class=\"btn pri\" type=\"button\" data-act=\"nbsave\">保存して、いま書き出す</button>${n.doc_url ? `<a class=\"btn\" href=\"${esc(n.doc_url)}\" target=\"_blank\" rel=\"noopener\">ドキュメントを別タブで開く ↗</a>` : \"\"}</div>\n      <div class=\"hint\">最後に書き出した：${esc(n.at || \"まだ\")}${n.error ? `<br><span style=\"color:var(--s-wait)\">止まっている理由：${esc(n.error)}</span>` : \"\"}</div>\n      <div class=\"hint\">3. NotebookLM でノートを開き、ソースの追加から Google ドライブのこのドキュメントを選ぶ（最初の1回だけ）</div>\n    </div></div>`;\n}\nasync function openNotebook() {\n  S.view = \"notebook\"; S.sel = null; S.pin = null; S.full = null; setHash(\"\"); render();\n  try { const b = await api(\"notebook\"); S.nb = b; render(); } catch (e) { toast(e.message); }\n}\nasync function saveNotebook() {\n  const v = ($(\"#nbdoc\") || {}).value || \"\";\n  try { const b = await api(\"notebook\", { method: \"POST\", body: JSON.stringify({ doc: v }) }); S.nb = b; render(); toast(b.message || \"書き出しました\"); }\n  catch (e) { toast(e.message); try { S.nb = await api(\"notebook\"); render(); } catch {} }\n}\nfunction detailHtml() {\n  if (S.view === \"notebook\" && !S.sel) return notebookHtml();\n  if (S.view === \"activity\" && !S.sel && S.act) return activityHtml();\n  if (S.view === \"work\" && !S.sel) return workHtml();\n  if (!S.sel) return `<div class=\"empty\" style=\"margin-top:12vh\">チャットを押すと、やったこととピンが開きます。<br>何をやったかを分野をまたいで見るときは「今日やったこと」。</div>`;\n  const c = S.chat;\n  if (!c || c.番号 !== S.sel) return `<div class=\"empty\">読み込んでいます…</div>`;\n  const back = `<button class=\"back\" data-act=\"back\">← 一覧へ</button>`;\n  if (S.full) {\n    const f = S.full;\n    return back + `<button class=\"back\" style=\"display:inline-flex\" data-act=\"toc\">← ${esc(c.名前)} の目次へ</button>\n    <div class=\"card\"><div class=\"meta\"><span>チャット ${c.番号}</span><span>${f.往復 ?? \"?\"} 往復</span><span>読んだ ${esc(f.読んだ || \"\")}</span><span>${(f.全文 || \"\").length.toLocaleString()} 字</span></div>\n      <h2 class=\"title\" style=\"margin-top:6px\">${esc(c.名前)} の全文</h2>\n      <div class=\"acts\"><button class=\"btn\" data-act=\"copyfull\">全文をコピー</button>${c.住所 ? `<a class=\"btn\" href=\"${esc(c.住所)}\" target=\"_blank\" rel=\"noopener\">チャットを別タブで開く ↗</a>` : \"\"}</div></div>\n    <div class=\"card body\">${md(f.全文 || \"\")}</div>`;\n  }\n  if (S.pin) {\n    const p = S.pin;\n    return back + `<button class=\"back\" style=\"display:inline-flex\" data-act=\"toc\">← ${esc(c.名前)} の目次へ</button>\n    <div class=\"card\"><div class=\"meta\"><span class=\"ref\" style=\"font-weight:800;color:var(--brand)\">ピン</span><span>${esc(c.名前)}</span><span>${esc(p.作った)}</span><span>${p.字数.toLocaleString()} 字</span></div>\n      <h2 class=\"title\" style=\"margin-top:6px\">${esc(p.題)}</h2>\n      <div class=\"acts\"><button class=\"btn pri\" data-act=\"copyref\">頼み方をコピー</button><button class=\"btn\" data-act=\"copybody\">全文をコピー</button>${c.住所 ? `<a class=\"btn\" href=\"${esc(c.住所)}\" target=\"_blank\" rel=\"noopener\">チャットを別タブで開く ↗</a>` : \"\"}</div></div>\n    <div class=\"card body\">${md(p.全文)}</div>`;\n  }\n  const form = S.editing ? `<form class=\"form\" id=\"edit\">\n      <label>状態<select name=\"state\">${STATES.map((s) => `<option${s === c.状態 ? \" selected\" : \"\"}>${s}</option>`).join(\"\")}</select></label>\n      <label>何をしているか・何を決めてほしいか（1 行）<input name=\"doing\" maxlength=\"200\" value=\"${esc(c.何をしているか)}\"></label>\n      <label>分野（棚の名前。空にするとプロジェクト名が自動で入る）<input name=\"area\" maxlength=\"60\" list=\"areas\" value=\"${esc(c.分野 || \"\")}\"><datalist id=\"areas\">${S.areas.filter((a) => a.分野 !== \"未分類\").map((a) => `<option value=\"${esc(a.分野)}\">`).join(\"\")}</datalist></label>\n      <label>作業（同じ分野の開いている作業から選ぶか、新しい名前を書く。空にすると作業から外す）<input name=\"work\" maxlength=\"80\" list=\"works\" value=\"${esc(c.作業 ? c.作業.名前 : \"\")}\"><datalist id=\"works\">${worksIn(c.分野 || \"未分類\").map((w) => `<option value=\"${esc(w.名前)}\">`).join(\"\")}</datalist></label>\n      <label>名前<input name=\"name\" maxlength=\"120\" value=\"${esc(c.名前)}\" required></label>\n      <label>チャットの住所<input name=\"url\" maxlength=\"500\" placeholder=\"https://\" value=\"${esc(c.住所 || \"\")}\"></label>\n      <label>haAku の取り組み<select name=\"initiative\"><option value=\"\">（結ばない）</option>${S.inis.map((i) => `<option value=\"${esc(i.no)}\"${c.取り組み && c.取り組み.番号 === i.no ? \" selected\" : \"\"}>${esc(i.no + \" \" + i.name)}</option>`).join(\"\")}</select></label>\n      <div class=\"acts\" style=\"margin-top:0\"><button class=\"btn pri\" type=\"submit\">保存</button><button class=\"btn\" type=\"button\" data-act=\"cancel\">キャンセル</button><span class=\"hint\">⌘／Ctrl＋Enter で保存</span></div></form>` : \"\";\n  return back + `<div class=\"card\">\n    <h2 class=\"title\">${esc(c.名前)}</h2>\n    <div class=\"meta\">${stBadge(c.状態)}${aiBadge(c.AI)}<span class=\"area\">${esc(c.分野 || \"未分類\")}</span>${c.作業 ? `<button class=\"wchip\" data-work=\"${c.作業.番号}\">作業：${esc(c.作業.名前)}</button>` : \"\"}${c.役割 && c.役割 !== c.分野 ? `<span>${esc(c.役割)}</span>` : \"\"}${c.取り組み ? `<span>取り組み ${esc(c.取り組み.番号 + \" \" + c.取り組み.名前)}</span>` : \"\"}<span>最後に触った ${esc(c.最後に触った)}</span><span>作った ${esc(c.作った)}</span></div>\n    ${c.何をしているか ? `<div class=\"doing\"><div class=\"k\">${c.状態 === \"判断待ち\" ? \"決めてほしいこと\" : \"何をしているか\"}</div>${esc(c.何をしているか)}</div>` : \"\"}\n    ${S.editing ? form : `<div class=\"acts\">${c.住所 ? `<a class=\"btn pri\" href=\"${esc(c.住所)}\" target=\"_blank\" rel=\"noopener\">チャットを別タブで開く ↗</a>` : `<span class=\"hint\">住所はまだありません（編集で入れられます）</span>`}${c.全文を読んだ ? `<button class=\"btn\" data-act=\"full\">全文を見る（${c.往復} 往復）</button>` : \"\"}${c.判断のタスク ? `<a class=\"btn\" href=\"${esc(c.判断のタスク)}\" target=\"_blank\" rel=\"noopener\">判断のタスクを別タブで開く ↗</a>` : \"\"}<button class=\"btn\" data-act=\"edit\">編集</button></div>`}\n    ${S.ses && S.ses.length ? `<div class=\"hint\" style=\"margin-top:10px\">Notion の Sessions：${S.ses.map((x) => `<a href=\"${esc(x.url)}\" target=\"_blank\" rel=\"noopener\">${esc(x.title)} ↗</a>`).join(\"・\")}</div>` : \"\"}\n  </div>\n  <div class=\"card\"><h3 class=\"sec\">やったこと（${S.done.length}）</h3>\n    ${S.done.length ? `<ul class=\"tl\">${S.done.map((d) => `<li><span class=\"tm\">${esc(String(d.時刻).slice(5).replace(\"-\", \"/\"))}</span><span class=\"tx\">${esc(d.やったこと)}</span></li>`).join(\"\")}</ul>`\n      : S.ask ? `<ul class=\"tl\"><li class=\"ask\"><span class=\"tm\">${esc(String(c.全文を読んだ || c.最後に触った).slice(5).replace(\"-\", \"/\"))}</span><span class=\"tx\">${esc(S.ask)}</span></li></ul><div class=\"hint\" style=\"margin-top:6px\">このチャットはまだ「やったこと」を残していないので、最後の頼みごとを出しています。</div>`\n      : `<div class=\"hint\">まだありません。チャットが区切りごとに「○○をした」を残すと、ここに時系列で並びます。</div>`}\n  </div>\n  <div class=\"card\"><h3 class=\"sec\">ピン（${S.pins.length}）</h3>\n    ${S.pins.length ? `<div class=\"pins\">${S.pins.map((p) => `<button class=\"pin\" data-pin=\"${c.番号}-${p.番号}\"><span class=\"t\">${esc(p.題)}</span><span class=\"d\">${esc(p.作った)}</span></button>`).join(\"\")}</div>`\n      : `<div class=\"hint\">まだピンはありません。チャットで回答のあとに「これピン」と言うと、ここに全文が残ります。</div>`}\n  </div>`;\n}\nfunction render() {\n  if (!auth.currentUser) return;\n  let w = $(\".wrap\");\n  if (!w) {\n    app.innerHTML = `<div class=\"wrap\"><nav class=\"shelf\" aria-label=\"分野の棚\"></nav><aside class=\"side\" aria-label=\"チャットの一覧\">\n      <div class=\"seg\" role=\"tablist\" aria-label=\"見るもの\"><button type=\"button\" role=\"tab\" data-seg=\"works\">作業</button><button type=\"button\" role=\"tab\" data-seg=\"chats\">チャット</button><button type=\"button\" role=\"tab\" data-seg=\"today\">今日</button></div>\n      <div class=\"tools\"><div class=\"search\"><label class=\"sr\" for=\"q\">探す</label><input id=\"q\" type=\"search\" placeholder=\"名前・何をしているか・ピンと全文から探す\" autocomplete=\"off\"><button class=\"x\" data-act=\"clear\" aria-label=\"検索を消す\" hidden>✕</button></div>\n      <div class=\"tabs\" role=\"group\" aria-label=\"状態で絞る\"></div>\n      <details class=\"filt\"><summary>絞り込み</summary><div class=\"in\">\n        <div class=\"row2\"><label for=\"ai\">AI</label><select id=\"ai\"><option value=\"\">すべて</option><option value=\"claude\">Claude</option><option value=\"gpt\">GPT</option></select><label for=\"ini\">取り組み</label><select id=\"ini\" style=\"max-width:120px\"><option value=\"\">すべて</option></select><span class=\"grow\"></span><span class=\"cnt\"></span></div>\n        <div class=\"row2\"><span class=\"areasel\"><label for=\"area\">分野</label><select id=\"area\" style=\"max-width:170px\"></select></span></div>\n        <div class=\"row2 nbnarrow\"><button class=\"tab\" data-act=\"notebook\" type=\"button\">NotebookLM へ書き出す</button></div>\n      </div></details></div>\n      ${PANEL ? '<div class=\"ext\" role=\"status\"></div>' : \"\"}<div class=\"list\" role=\"list\"></div></aside><main class=\"main\"><div class=\"pane\"></div></main></div>`;\n    w = $(\".wrap\");\n    $(\"#q\").addEventListener(\"input\", (e) => { onSearch(e.target.value); $(\"[data-act=clear]\").hidden = !e.target.value; });\n    $(\"#ai\").addEventListener(\"change\", (e) => { S.ai = e.target.value; loadList(); });\n    $(\"#ini\").addEventListener(\"change\", (e) => { S.ini = e.target.value; loadList(); });\n    $(\"#area\").addEventListener(\"change\", (e) => setArea(e.target.value));\n    const narrow = matchMedia(\"(max-width:1100px)\");\n    const setFilt = () => { const d = $(\".filt\"); if (d) d.open = !narrow.matches; };\n    setFilt(); narrow.addEventListener(\"change\", () => { setFilt(); render(); });\n    api(\"initiatives\").then((b) => { S.inis = b.initiatives || []; const sel = $(\"#ini\"); if (sel) sel.innerHTML = '<option value=\"\">すべて</option>' + S.inis.map((i) => `<option value=\"${esc(i.no)}\">${esc(i.no + \" \" + i.name)}</option>`).join(\"\"); }).catch(() => {});\n    if (PANEL) { renderExt(); toPanel({ type: \"ext-hello\" }); }\n  }\n  $(\".tabs\").innerHTML = tabsHtml();\n  $(\".shelf\").innerHTML = shelfHtml();\n  $(\"#area\").innerHTML = areaSelHtml();\n  const nar = matchMedia(\"(max-width:1100px)\").matches;\n  const seg = S.view === \"activity\" ? \"today\" : S.seg;\n  $$(\".seg [data-seg]\").forEach((b) => b.setAttribute(\"aria-selected\", String(b.dataset.seg === seg)));\n  $(\".side\").classList.toggle(\"s-works\", nar && S.seg === \"works\" && !S.hits);\n  $(\".list\").innerHTML = listHtml();\n  $(\".cnt\").textContent = S.hits ? S.hits.length + \" 件当たり\" : S.chats.length + \" 本\";\n  $(\".pane\").innerHTML = detailHtml();\n  w.classList.toggle(\"detail\", !!S.sel || S.view === \"notebook\" || S.view === \"activity\" || S.view === \"work\");\n  const wf = $(\"#wedit\");\n  if (wf) wf.addEventListener(\"submit\", (e) => { e.preventDefault(); const fd = new FormData(wf); const to = +fd.get(\"to\"); if (to) workMerge(to); else workUpdate({ name: fd.get(\"name\") }, \"名前を直しました\"); });\n  const f = $(\"#edit\");\n  if (f) {\n    f.addEventListener(\"submit\", (e) => { e.preventDefault(); save(f); });\n    f.addEventListener(\"keydown\", (e) => { if (e.key === \"Enter\" && (e.metaKey || e.ctrlKey)) { e.preventDefault(); save(f); } else if (e.key === \"Escape\") { S.editing = false; render(); } });\n  }\n}\ndocument.addEventListener(\"click\", (e) => {\n  const t = e.target.closest(\"[data-chat],[data-pin],[data-filter],[data-act],[data-area],[data-work],[data-toggle],[data-seg]\");\n  if (!t || !app.contains(t)) return;\n  if (t.dataset.filter) { S.filter = t.dataset.filter; try { localStorage.setItem(\"mk:filter\", S.filter); } catch {} loadList(); return; }\n  if (t.dataset.seg) {\n    const g = t.dataset.seg;\n    if (g === \"today\") { openActivity(\"today\"); return; }\n    S.seg = g; try { localStorage.setItem(\"mk:seg\", g); } catch {}\n    if (S.view === \"activity\") { S.view = null; setHash(\"\"); }\n    render(); return;\n  }\n  if (t.dataset.toggle !== undefined) { toggleArea(t.dataset.toggle); return; }\n  if (t.dataset.work) { openWork(+t.dataset.work); return; }\n  if (t.dataset.area !== undefined && !t.dataset.act) { setArea(t.dataset.area); return; }\n  if (t.dataset.chat) { openChat(+t.dataset.chat); return; }\n  if (t.dataset.pin) { const [c, n] = t.dataset.pin.split(\"-\").map(Number); if (S.sel !== c || !S.chat || S.chat.番号 !== c) openChat(c, n); else openPin(c, n); return; }\n  const a = t.dataset.act;\n  if (a === \"back\") { S.sel = null; S.pin = null; S.full = null; S.view = null; S.work = null; setHash(\"\"); setTabTitle(\"チャット\"); render(); }\n  else if (a === \"toc\") { S.pin = null; S.full = null; setHash(`#c${S.sel}`); setTabTitle(S.chat.名前, \"チャット\"); render(); }\n  else if (a === \"edit\") { S.editing = true; render(); const s = $(\"#edit select\"); if (s) s.focus(); }\n  else if (a === \"cancel\") { S.editing = false; render(); $(\"[data-act=edit]\")?.focus(); }\n  else if (a === \"copyref\") copy(`マネージャーくんの「${S.pin.題}」のピンを持ってきて`, \"頼み方をコピーしました\");\n  else if (a === \"copybody\") copy(S.pin.全文, \"全文をコピーしました\");\n  else if (a === \"copyfull\") copy(S.full.全文 || \"\", \"全文をコピーしました\");\n  else if (a === \"full\") openFull();\n  else if (a === \"notebook\") openNotebook();\n  else if (a === \"wopen\") workTabs(\"tabs-open\");\n  else if (a === \"wfold\") workTabs(\"tabs-collapse\");\n  else if (a === \"wclose\") workTabs(\"tabs-close\");\n  else if (a === \"wdone\") workUpdate({ state: \"済み\" }, \"作業を済みにしました\");\n  else if (a === \"wreopen\") workUpdate({ state: \"進行中\" }, \"作業を進行中に戻しました\");\n  else if (a === \"wedit\") { S.wedit = true; render(); }\n  else if (a === \"wcancel\") { S.wedit = false; render(); }\n  else if (a === \"act-today\") openActivity(\"today\");\n  else if (a === \"act-week\") openActivity(\"week\");\n  else if (a === \"nbsave\") saveNotebook();\n  else if (a === \"copysa\") copy((S.nb && S.nb.share_to) || \"\", \"メールアドレスをコピーしました\");\n  else if (a === \"extconnect\") extConnect();\n  else if (a === \"extrevoke\") extRevoke();\n  else if (a === \"clear\") { const q = $(\"#q\"); q.value = \"\"; onSearch(\"\"); t.hidden = true; q.focus(); }\n});\ndocument.addEventListener(\"keydown\", (e) => {\n  if (e.key === \"/\" && !/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName || \"\") && !shell.isOpen()) { e.preventDefault(); $(\"#q\")?.focus(); }\n});\nwindow.addEventListener(\"popstate\", () => { const h = readHash(); if (h.chat) openChat(h.chat, h.pin, false); else if (h.work) openWork(h.work, false); else { S.sel = null; S.pin = null; S.view = null; render(); } });\n\n/* ---- ログイン ---- */\nfunction loginView(msg) {\n  app.innerHTML = `<div class=\"login\"><img src=\"/manager/favicon.svg\" width=\"48\" height=\"48\" alt=\"\"><h2>マネージャーくん</h2><p>${esc(msg || \"Naoki の Google アカウントでログインしてください。\")}</p><button class=\"btn pri\" id=\"login\">Google でログイン</button></div>`;\n  $(\"#login\").addEventListener(\"click\", () => auth.signInWithPopup(new firebase.auth.GoogleAuthProvider()).catch((e) => loginView(\"ログインできませんでした（\" + (e.code || e.message) + \"）\")));\n}\nsetTabTitle(\"チャット\");\nauth.onAuthStateChanged(async (u) => {\n  if (!u) { loginView(); return; }\n  app.innerHTML = \"\"; await loadList();\n  const h = readHash(); if (h.chat) openChat(h.chat, h.pin, false); else if (h.work) openWork(h.work, false);\n});\n</script>\n</body>\n</html>\n";

export function managerPage(): string {
  return HTML.replace("__FIREBASE_WEB__", JSON.stringify(FIREBASE_WEB));
}
